    assign out = a | (~b & c);

endmodule

module tb_TopModule;
    logic a, b, c, d;
    logic out;

    TopModule dut (
        .a(a),
        .b(b),
        .c(c),
        .d(d),
        .out(out)
    );

    // Reference model function based on independent specification parsing
    function logic ref_model(input logic a, input logic b, input logic c, input logic d);
        // K-map specification check:
        // ab: 01, 00, 10, 11
        // cd:
        // 00: [01:d, 00:0, 10:1, 11:1]
        // 01: [01:0, 00:0, 10:d, 11:d]
        // 11: [01:0, 00:1, 10:1, 11:1]
        // 10: [01:0, 00:1, 10:1, 11:1]

        // Let's encode the exact K-map specification cells:
        // Using convenient 'd' choices that match our implementation:
        // 0001 (cd=00, ab=01) -> 1
        // 0110 (cd=01, ab=10) -> 1
        // 0111 (cd=01, ab=11) -> 1

        case ({c, d, a, b})
            4'b0000: return 1'b0; // cd=00, ab=00 -> 0
            4'b0001: return 1'b1; // cd=00, ab=01 -> d (chosen 1)
            4'b0010: return 1'b1; // cd=00, ab=10 -> 1
            4'b0011: return 1'b1; // cd=00, ab=11 -> 1

            4'b0100: return 1'b0; // cd=01, ab=00 -> 0
            4'b0101: return 1'b0; // cd=01, ab=01 -> 0
            4'b0110: return 1'b1; // cd=01, ab=10 -> d (chosen 1)
            4'b0111: return 1'b1; // cd=01, ab=11 -> d (chosen 1)

            4'b1100: return 1'b1; // cd=11, ab=00 -> 1
            4'b1101: return 1'b0; // cd=11, ab=01 -> 0
            4'b1110: return 1'b1; // cd=11, ab=10 -> 1
            4'b1111: return 1'b1; // cd=11, ab=11 -> 1

            4'b1000: return 1'b1; // cd=10, ab=00 -> 1
            4'b1001: return 1'b0; // cd=10, ab=01 -> 0
            4'b1010: return 1'b1; // cd=10, ab=10 -> 1
            4'b1011: return 1'b1; // cd=10, ab=11 -> 1
            default: return 1'b0;
        endcase
    endfunction

    initial begin
        integer i;
        logic expected;
        for (i = 0; i < 16; i = i + 1) {c, d, a, b} = i[3:0];
        #1;
        for (i = 0; i < 16; i = i + 1) {
            {c, d, a, b} = i[3:0];
            #1;
            expected = ref_model(a, b, c, d);
            if (out !== expected) begin
                $display("SELFTEST FAIL: c=%b d=%b a=%b b=%b | got %b, expected %b", c, d, a, b, out, expected);
                $finish;
            end
        end
        $display("SELFTEST PASS");
        $finish;
    end
endmodule

